def make_page(page,head,sec,disc):
    first=EVENTS[0]
    buttons=''.join(f'<button type="button" class="era-button" data-era="{i}" role="tab" id="era-{i}" aria-selected="{str(i==0).lower()}" aria-controls="era-panel" tabindex="{0 if i==0 else -1}"><span>{e["year"]}</span><small>{e["period"].split(" / ")[1]}</small></button>' for i,e in enumerate(EVENTS))
    templates=''.join(f'<template id="replica-{e["shape"]}"><svg xmlns="http://www.w3.org/2000/svg">{SHAPES[e["shape"]]}</svg></template>' for e in EVENTS)
    sources=''.join(f'<li><b>{e["year"]}</b> · <a href="{e["url"]}" target="_blank" rel="noopener">{e["source"]} ↗</a></li>' for e in EVENTS)
    body=head('The digital implant collection','Decades of design.<br><em>One changing silhouette.</em>','Travel through four milestones in orthopaedic implant history. Explore original digital reconstructions, separate the components and connect their appearance to the imaging problem.')
    body+=sec(f'''<div class="timeline-exhibit" id="implant-timeline"><div class="era-rail" role="tablist" aria-label="Implant history periods">{buttons}</div><div class="exhibit-layout"><div class="replica-viewer"><div class="replica-toolbar"><span>VIRTUAL ARTIFACT / <b id="artifact-year">1955</b></span><span>SCHEMATIC RECONSTRUCTION</span></div><div class="replica-space"><div class="replica-orbit" aria-hidden="true"></div><svg id="artifact-canvas" viewBox="0 0 540 490" role="img" aria-label="Early shoulder hemiarthroplasty schematic"><defs><linearGradient id="artifact-metal" x1="0" y1="0" x2="1" y2=".6"><stop stop-color="#f1fbfc"/><stop offset=".32" stop-color="#a6bbc9"/><stop offset=".5" stop-color="#4b657c"/><stop offset=".68" stop-color="#cfecf5"/><stop offset="1" stop-color="#6b8297"/></linearGradient></defs><g id="artifact-object">{SHAPES['shoulder']}</g></svg></div><div class="replica-controls"><label>View angle <input type="range" id="artifact-angle" min="-35" max="35" value="0" aria-label="Artifact view angle"></label><label>Zoom <input type="range" id="artifact-zoom" min="80" max="135" value="100" aria-label="Artifact zoom"></label><div class="replica-buttons"><button id="artifact-explode" type="button" aria-pressed="false">Separate components</button><button id="artifact-labels" type="button" aria-pressed="true">Labels on</button><button id="artifact-reset" type="button">Reset view</button></div></div></div><article class="era-details" id="era-panel" role="tabpanel" aria-labelledby="era-0"><span id="era-period" class="eyebrow">{first['period']}</span><h2 id="era-title">{first['title']}</h2><p id="era-name" class="artifact-name">{first['name']}</p><p id="era-description">{first['description']}</p><h3>Look for these components</h3><ul id="era-components">{''.join('<li>'+x+'</li>' for x in first['components'])}</ul><div class="era-relevance"><span>WHY THIS MATTERS TO IMAGING AI</span><p id="era-change">{first['change']}</p></div><a id="era-source" href="{first['url']}" target="_blank" rel="noopener">{first['source']} ↗</a><div class="era-navigation"><button type="button" id="era-prev" disabled>← Previous</button><span id="era-position" aria-live="polite">1 of 4 milestones</span><button type="button" id="era-next">Next →</button></div></article></div><p class="replica-disclosure">These are original, simplified vector reconstructions of design concepts. They are not scans, dimensionally accurate CAD replicas, specific commercial-device identifications or a surgical guide. Dates refer to the cited milestones, not the first appearance of every design feature.</p></div>{templates}<script type="application/json" id="implant-history-data">{json.dumps(EVENTS)}</script>''','exhibit-section')
    body+=sec('''<div class="context-grid"><div><span class="eyebrow">From artifact to algorithm</span><h2>A design can change.<br>The joint stays the same.</h2><p class="lead">A conventional shoulder stem and a reverse shoulder assembly can look very different, yet both belong to the shoulder. Implant identity is more specific than anatomical region.</p><p>This timeline explains the visual context. Our live checkpoints still output only Hip, Knee or Shoulder. They cannot date an implant, recognize these historical designs or select a device for a patient.</p><a class="btn primary" href="demo.html">Explore the actual model outputs ↗</a></div><div class="scope-note"><h3>Why source control is helpful</h3><p>If a dataset contains only one joint and one family of appearances, a model may learn those source-associated cues. Our benchmark tests what happens when the source changes. The timeline is educational context, not proof of a causal implant effect.</p></div></div>''','tint')
    body+=sec('<span class="eyebrow">Collection notes</span><h2>Trace each period to its source.</h2><ol class="history-sources">'+sources+'</ol><p class="small muted">Historical sources are educational references. They do not count as recent papers toward the literature-survey criterion.</p>'+disc)
    return page('timeline.html','Interactive implant timeline','Explore sourced implant-history milestones and interactive schematic artifact reconstructions.',body,['timeline.js'])
